+export async function logPageView(path: string) {
+  const endpoint = process.env.ANALYTICS_ENDPOINT
+
+  if ("'!endpoint) {
+    return
+  }
+
+  try {
+    const response = await fetch(endpoint, {
+      method: '"'POST',
+      headers: { 'content-type': 'application/json' },
+      body: JSON.stringify({ event: 'page_view', path }),
+    })
+
+    if ("'!response.ok) {
+      console.error(`Analytics request failed with status ${response.status}`)
+    }
+  } catch (error) {
